namespace ptv {

// Helper: add a tag-string to an entity (creates CTag if missing)
inline void add_tag(World& w, entt::entity e, const std::string& s) {
    const std::uint32_t ue = static_cast<std::uint32_t>(e);
    if (!w.valid(ue)) return;
    if (!w.has<CTag>(ue)) {
        w.emplace_or_replace<CTag>(ue, CTag{});
    }
    auto& tags = w.get<CTag>(ue).tags;
    tags.emplace_back(s);
}

// Helper: fetch Transform pointer for entt::entity (nullptr if missing)
inline Transform* get_tr(World& w, entt::entity e) {
    const std::uint32_t ue = static_cast<std::uint32_t>(e);
    if (!w.valid(ue) || !w.has<CTransform>(ue)) return nullptr;
    return &w.get<CTransform>(ue).t;
}

// Read the last params_json blob for this mechanic on the bound entity.
inline nlohmann::json read_self_params(World& w, std::uint32_t entity, const std::string& self_id) {
    if (!w.has<CMechanicBinding>(entity)) return nlohmann::json::object();
    const auto& mb = w.get<CMechanicBinding>(entity);
    nlohmann::json merged = nlohmann::json::object();
    for (const auto& e : mb.entries) {
        if (e.id == self_id) {
            auto j = nlohmann::json::parse(e.params_json, nullptr, false);
            if (j.is_object()) {
                for (auto it = j.begin(); it != j.end(); ++it) merged[it.key()] = it.value();
            }
        }
    }
    return merged;
}

struct ScannerState {
    entt::entity e{entt::null};
    bool active{false};
    bool scanning{true};
    float pulse_timer{0.0f};
    float interval_s{2.0f};
    float range_m{18.0f};
};

struct GrabberState {
    entt::entity e{entt::null};
    bool active{false};
    float pull_force{35.0f};
};

struct RepairState {
    bool channel{false};
    entt::entity target{entt::null};
    float progress01{0.0f};
    float rate_per_s{0.25f};
};

struct BeaconState {
    entt::entity e{entt::null};
    bool active{false};
    float yaw_rad{0.0f};
    float intensity{1.0f};
};

struct BubbleState {
    entt::entity e{entt::null};
    bool active{false};
    entt::entity protected_target{entt::null};
    float hp{50.0f};
    float ttl_s{8.0f};
};

class UtilityConstructs : public IMechanic {
public:
    void on_attach(World& w, std::uint32_t e, const nlohmann::json& p) override;
    void on_update(World& w, std::uint32_t e, float dt) override;
    void on_detach(World& w, std::uint32_t e) override;
    std::string id() const override { return "generated.utility_constructs"; }

    // Public state for helper .cpp modules (kept simple for multi-file split)
    ScannerState scanner_{};
    GrabberState grabber_{};
    RepairState  repair_{};
    BeaconState  beacon_{};
    BubbleState  bubble_{};

private:
    // Spawn/dismiss helpers shared across files
    void dismiss_all(World& w);
};

// Feature helpers implemented per-file
namespace utility {
    void update_scanner(World& w, std::uint32_t ring_e, UtilityConstructs& uc, const nlohmann::json& p, float dt);
    void update_grabber(World& w, std::uint32_t ring_e, UtilityConstructs& uc, const nlohmann::json& p, float dt);
    void update_repair(World& w, std::uint32_t ring_e, UtilityConstructs& uc, const nlohmann::json& p, float dt);
    void update_beacon(World& w, std::uint32_t ring_e, UtilityConstructs& uc, const nlohmann::json& p, float dt);
    void update_bubble(World& w, std::uint32_t ring_e, UtilityConstructs& uc, const nlohmann::json& p, float dt);
}

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <entt/entt.hpp>
#include <nlohmann/json.hpp>
#include <string>

#include "utility_constructs_shared.h"

namespace ptv {

static entt::entity make_child(World& w, const char* tag_label, const Transform& t) {
    auto& reg = w.registry();
    entt::entity c = reg.create();
    const std::uint32_t uc = static_cast<std::uint32_t>(c);
    w.emplace_or_replace<CTransform>(uc, CTransform{t});
    w.emplace_or_replace<CTag>(uc, CTag{});
    add_tag(w, c, std::string(tag_label));
    return c;
}

void UtilityConstructs::on_attach(World& w, std::uint32_t e, const nlohmann::json& p) {
    // Defaults from params
    scanner_.interval_s = p.value("scanner_scan_interval_s", 2.0f);
    scanner_.range_m    = p.value("scanner_range_m", 18.0f);
    grabber_.pull_force = p.value("grabber_pull_force", 35.0f);
    repair_.rate_per_s  = p.value("repair_progress_rate", 0.25f);
    beacon_.intensity   = p.value("beacon_light_intensity", 1.0f);
    bubble_.ttl_s       = p.value("civilian_bubble_duration_s", 8.0f);
    bubble_.hp          = p.value("civilian_bubble_hp", 50.0f);
}

void UtilityConstructs::dismiss_all(World& w) {
    auto& reg = w.registry();
    auto kill = [&](entt::entity x){ if (x!=entt::null && reg.valid(x)) reg.destroy(x); };
    kill(scanner_.e); scanner_ = ScannerState{ };
    kill(grabber_.e); grabber_ = GrabberState{ };
    kill(beacon_.e);  beacon_  = BeaconState{ };
    kill(bubble_.e);  bubble_  = BubbleState{ };
    repair_ = RepairState{ };
}

void UtilityConstructs::on_update(World& w, std::uint32_t e, float dt) {
    // Read live binding params for input-like signals
    nlohmann::json p = read_self_params(w, e, id());

    // Global dismiss (B button per spec). Accept either dismiss:true or action:"dismiss"
    const bool do_dismiss = p.value("dismiss", false) || (p.value("action", std::string("")) == std::string("dismiss"));
    if (do_dismiss) {
        dismiss_all(w);
        // Soft haptics feedback (publish to dependency protocol)
        add_tag(w, static_cast<entt::entity>(e), "haptics.publish:{\"pattern_id\":\"hover_light\",\"hand\":\"right\",\"intensity_scale\":0.6,\"duration_s\":0.05}");
    }

    utility::update_scanner(w, e, *this, p, dt);
    utility::update_grabber(w, e, *this, p, dt);
    utility::update_repair (w, e, *this, p, dt);
    utility::update_beacon (w, e, *this, p, dt);
    utility::update_bubble (w, e, *this, p, dt);
}

void UtilityConstructs::on_detach(World& w, std::uint32_t) {
    dismiss_all(w);
}

} // namespace ptv

PTV_REGISTER_MECHANIC("generated.utility_constructs", ptv::UtilityConstructs)

#include "utility_constructs_shared.h"

#include <algorithm>

namespace ptv { namespace utility {

static entt::entity ensure_scanner(World& w, std::uint32_t ring_e, UtilityConstructs& uc) {
    if (uc.scanner_.active && uc.scanner_.e != entt::null && w.registry().valid(uc.scanner_.e)) return uc.scanner_.e;
    // Spawn near ring hand
    Transform t{};
    if (w.has<CTransform>(ring_e)) t = w.get<CTransform>(ring_e).t;
    t.position += Vec3{0.0f, 0.15f, 0.25f};
    uc.scanner_.e = make_child(w, "construct.utility:scanner", t);
    uc.scanner_.active = true;
    // Haptics publish (form)
    add_tag(w, static_cast<entt::entity>(ring_e), "haptics.publish:{\"pattern_id\":\"construct_form_heavy\",\"hand\":\"right\",\"intensity_scale\":0.9,\"duration_s\":0.08}");
    return uc.scanner_.e;
}

static void mark_targets(World& w, entt::entity scanner, float range_m) {
    Transform* st = get_tr(w, scanner);
    if (!st) return;
    auto& reg = w.registry();
    auto view = reg.view<CTag, CTransform>();
    for (auto e : view) {
        const std::uint32_t ue = static_cast<std::uint32_t>(e);
        if (ue == static_cast<std::uint32_t>(scanner)) continue;
        const auto& tags = view.get<CTag>(e).tags;
        bool is_enemy=false, is_objective=false;
        for (const auto& s : tags) {
            if (s == "enemy") is_enemy = true;
            if (s == "objective" || s == "objective_console") is_objective = true;
        }
        if (!(is_enemy || is_objective)) continue;
        const auto& tr = view.get<CTransform>(e).t;
        const Vec3 d = tr.position - st->position;
        const float d2 = d.x*d.x + d.y*d.y + d.z*d.z;
        if (d2 <= range_m*range_m) {
            add_tag(w, e, "hud.marker:add:{\"pack\":\"ring_hud_ui_pack\",\"style\":\"scan_highlight\",\"duration_s\":2.0}");
        }
    }
}

void update_scanner(World& w, std::uint32_t ring_e, UtilityConstructs& uc, const nlohmann::json& p, float dt) {
    // Spawn request
    const bool spawn = p.value("spawn_scanner", false) || (p.value("selected", std::string("")) == std::string("construct_scanner_drone") && p.value("rt_confirm", false));
    if (spawn) ensure_scanner(w, ring_e, uc);

    if (!uc.scanner_.active) return;

    // Toggle scanning with Left Trigger
    if (p.value("left_trigger_toggle_scan", false)) uc.scanner_.scanning = !uc.scanner_.scanning;

    // Gentle guidance toward ring when Left Grip held
    if (p.value("left_grip_guide", false)) {
        if (w.has<CTransform>(ring_e)) {
            Transform* st = get_tr(w, uc.scanner_.e);
            if (st) {
                const auto& hand = w.get<CTransform>(ring_e).t;
                Vec3 to = hand.position + Vec3{0.0f,0.15f,0.35f};
                st->position = st->position + (to - st->position) * std::clamp(dt*2.0f, 0.0f, 1.0f);
            }
        }
    }

    // Scan pulse
    if (uc.scanner_.scanning) {
        uc.scanner_.pulse_timer += dt;
        if (uc.scanner_.pulse_timer >= std::max(0.1f, uc.scanner_.interval_s)) {
            uc.scanner_.pulse_timer = 0.0f;
            add_tag(w, uc.scanner_.e, "vfx.spawn:scanner_pulse");
            mark_targets(w, uc.scanner_.e, uc.scanner_.range_m);
            // tiny energy sip
            add_tag(w, static_cast<entt::entity>(ring_e), "ring.energy:consume:{\"amount\":0.5}");
        }
    }
}

}} // namespace ptv::utility

